begin;
set local statement_timeout='20s';
create function pg_temp.ok(v boolean,label text) returns void language plpgsql as $$begin if v is distinct from true then raise exception 'FAIL %',label;end if;raise notice 'PASS %',label;end;$$;
do $$
declare org uuid:=gen_random_uuid(); actor uuid:=gen_random_uuid(); other_actor uuid:=gen_random_uuid(); convo uuid:=gen_random_uuid(); source uuid:=gen_random_uuid(); req uuid:=gen_random_uuid(); msg public.department_chat_messages; replay public.department_chat_messages; a public.design_private_attachments;
begin
 insert into auth.users(id,email) values(actor,actor||'@example.invalid'),(other_actor,other_actor||'@example.invalid');
 insert into public.organizations(id,name,slug,status) values(org,'Synthetic attachment rollback','attachment-qa-'||org,'active');
 insert into public.organization_memberships(organization_id,user_id,role,department_id,status,member_kind) values(org,actor,'operations_admin','design','active','team'),(org,other_actor,'operations_admin','design','active','team');
 perform public.create_design_private_upload_conversation(org,actor,convo);
 perform public.create_design_private_upload_conversation(org,actor,convo);
 perform pg_temp.ok((select count(*)=1 from public.department_chat_conversations where id=convo),'same first-upload identity creates one conversation');
 perform pg_temp.ok((select count(*)=0 from public.department_chat_messages where conversation_id=convo),'first Upload creates no message');
 begin perform public.create_design_private_upload_conversation(org,other_actor,convo);raise exception 'FAIL other actor adopted conversation';exception when insufficient_privilege then raise notice 'PASS other actor cannot adopt conversation';end;
 a:=public.reserve_design_private_attachment(org,convo,actor,source,'source.txt','text/plain',5,repeat('a',64),'internal',true);
 perform public.reserve_design_private_attachment(org,convo,actor,source,'source.txt','text/plain',5,repeat('a',64),'internal',true);
 perform pg_temp.ok((select count(*)=1 from public.design_private_attachments where id=source),'upload reservation stable replay');
 begin perform public.reserve_design_private_attachment(org,convo,actor,source,'different.txt','text/plain',5,repeat('a',64),'internal',true);raise exception 'FAIL changed inputs';exception when unique_violation then raise notice 'PASS same request different inputs conflicts';end;
 begin perform public.read_design_private_attachments(org,convo,other_actor);raise exception 'FAIL other actor read';exception when insufficient_privilege then raise notice 'PASS other actor read denied';end;
 begin perform public.read_design_private_attachments(gen_random_uuid(),convo,actor);raise exception 'FAIL other org read';exception when insufficient_privilege then raise notice 'PASS other organization denied';end;
 begin perform public.finalize_design_private_attachment(org,convo,actor,source,repeat('b',64),5,'text/plain','plain_text','hello','text');raise exception 'FAIL wrong hash';exception when check_violation then raise notice 'PASS checksum mismatch denied';end;
 perform public.finalize_design_private_attachment(org,convo,actor,source,repeat('a',64),5,'text/plain','plain_text','hello','text');
 perform public.finalize_design_private_attachment(org,convo,actor,source,repeat('a',64),5,'text/plain','plain_text','hello','text');
 perform pg_temp.ok((select status='ready' from public.design_private_attachments where id=source),'same finalization stable replay');
 begin perform public.finalize_design_private_attachment(org,convo,actor,source,repeat('a',64),5,'text/plain','plain_text','changed','text');raise exception 'FAIL changed extraction';exception when unique_violation then raise notice 'PASS finalized extraction immutable';end;
 msg:=public.append_design_private_message_sources(org,convo,actor,req,'Use this reference',array[source]);
 replay:=public.append_design_private_message_sources(org,convo,actor,req,'Use this reference',array[source]);
 perform pg_temp.ok(msg.id=replay.id,'message retry retains exact request');
 perform pg_temp.ok((select count(*)=1 from public.design_private_message_sources where message_id=msg.id),'one immutable source manifest');
 begin perform public.append_design_private_message_sources(org,convo,actor,req,'Use this reference','{}'::uuid[]);raise exception 'FAIL changed selection';exception when unique_violation then raise notice 'PASS changed selection conflicts';end;
 begin perform public.append_design_private_message_sources(org,convo,actor,gen_random_uuid(),'Duplicate selection',array[source,source]);raise exception 'FAIL duplicated sources';exception when invalid_parameter_value then raise notice 'PASS duplicate selection rejected';end;
 begin update public.design_private_attachments set original_name='changed.txt' where id=source;raise exception 'FAIL source identity mutation';exception when insufficient_privilege then raise notice 'PASS source identity immutable';end;
 begin update public.design_private_attachments set extracted_text='replaced' where id=source;raise exception 'FAIL extraction mutation';exception when insufficient_privilege then raise notice 'PASS extracted text immutable';end;
 perform public.revoke_design_private_attachment(org,convo,actor,source);
 begin perform public.append_design_private_message_sources(org,convo,actor,gen_random_uuid(),'Revoked source',array[source]);raise exception 'FAIL revoked send';exception when insufficient_privilege then raise notice 'PASS revoked source cannot create new turn';end;
 replay:=public.append_design_private_message_sources(org,convo,actor,req,'Use this reference',array[source]);
 perform pg_temp.ok(replay.id=msg.id,'revocation retains original message recovery without dispatch');
 perform pg_temp.ok((select count(*)=1 from public.design_private_message_sources where message_id=msg.id),'revocation preserves historical manifest');
 update public.organization_memberships set status='revoked' where organization_id=org and user_id=actor;
 begin perform public.read_design_private_attachments(org,convo,actor);raise exception 'FAIL revoked member reads';exception when insufficient_privilege then raise notice 'PASS revoked membership denies read';end;
 perform pg_temp.ok(not has_table_privilege('authenticated','public.design_private_attachments','select,insert,update,delete'),'authenticated table access closed');
 perform pg_temp.ok(not has_table_privilege('anon','public.design_private_message_sources','select,insert,update,delete'),'anonymous manifest access closed');
 perform pg_temp.ok(not has_function_privilege('authenticated','public.create_design_private_upload_conversation(uuid,uuid,uuid)','execute'),'direct actor-spoof RPC closed');
 perform pg_temp.ok(not has_table_privilege('service_role','public.design_private_message_sources','update,delete,truncate'),'service cannot rewrite or truncate source manifests');
 perform pg_temp.ok(not has_table_privilege('service_role','public.design_private_attachments','delete,truncate'),'service cannot delete or truncate originals');
 perform pg_temp.ok((select relrowsecurity from pg_class where oid='public.design_private_attachments'::regclass),'private attachment RLS enabled');
end;$$;
rollback;
